// Some portions generated by Claude Code
package org.eclipse.rdf4j.workbench.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;

import jakarta.servlet.http.Cookie;

/**
 * The signed-in user is decoded from the server credentials cookie exactly as the Workbench pages decode it.
 */
class ServerCredentialsTest {

	@Test
	void theUserIsTheTextBeforeTheFirstColonOfTheCredentials() {
		assertThat(userOf(btoa("alice:se:cret"))).isEqualTo("alice");
	}

	@Test
	void credentialsEncodedOneBytePerCharacterKeepNonAsciiUserNames() {
		// window.btoa encodes each character as one byte, so "å" is the single byte 0xE5.
		assertThat(userOf(btoa("Håvard:secret"))).isEqualTo("Håvard");
	}

	/**
	 * C15: the Connection page encodes the credentials as UTF-8 before base64, so that any user name and password can
	 * be stored (window.btoa alone fails on characters beyond Latin-1).
	 */
	@Test
	void credentialsEncodedAsUtf8KeepNonLatin1UserNames() {
		String cookie = Base64.getEncoder()
				.encodeToString("Håvard✓:pass✓".getBytes(StandardCharsets.UTF_8));

		assertThat(userOf(cookie)).isEqualTo("Håvard✓");
		assertThat(ServerCredentials.decode(cookie)).isEqualTo("Håvard✓:pass✓");
	}

	@Test
	void credentialsThatAreNotUtf8AreReadOneBytePerCharacterAsBefore() {
		assertThat(ServerCredentials.decode(btoa("Håvard:sécret"))).isEqualTo("Håvard:sécret");
		assertThat(ServerCredentials.decode("not base64!")).isNull();
	}

	@Test
	void requestsWithoutCredentialsAreAnonymous() {
		assertThat(ServerCredentials.userName(new MockHttpServletRequest())).isEmpty();
		assertThat(userOf("")).isEmpty();
	}

	@Test
	void aServerUserParameterOrCookieIsNotASignIn() {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.addParameter("server-user", "mallory");
		request.setCookies(new Cookie("server-user", "mallory"));

		assertThat(ServerCredentials.userName(request)).isEmpty();
	}

	@Test
	void valuesThatAreNotBase64AreAnonymous() {
		assertThat(userOf("alice:secret")).isEmpty();
	}

	@Test
	void credentialsWithoutAColonNameTheUserAndAQuotedEmptyUserIsAnonymous() {
		assertThat(userOf(btoa("alice"))).isEqualTo("alice");
		assertThat(userOf(btoa("\"\":secret"))).isEmpty();
	}

	private static String userOf(String cookieValue) {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setCookies(new Cookie("other", "x"), new Cookie(ServerCredentials.COOKIE, cookieValue));
		return ServerCredentials.userName(request);
	}

	private static String btoa(String credentials) {
		return Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.ISO_8859_1));
	}
}
